<?php require_once __DIR__.'/_base.php'; $title='Provider Verification'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$action=post('action');$map=['approve'=>'Approved','reject'=>'Rejected','suspend'=>'Suspended'];if(isset($map[$action])){$new=$map[$action];$pdo->prepare('UPDATE providers SET verification_status=?,account_status=? WHERE id=?')->execute([$new,$action==='suspend'?'Suspended':'Active',$id]);$s=$pdo->prepare('SELECT user_id,name FROM providers WHERE id=?');$s->execute([$id]);$p=$s->fetch();notify($pdo,'Verification update','Your provider verification status is now '.$new.'.',null,$id,'verification');flash('success','Provider updated.');}redirect('verification.php');}$st=$pdo->query("SELECT * FROM providers WHERE verification_status IN ('Pending','Rejected') ORDER BY created_at ASC");?><h2>Verification Queue</h2><div class="row g-3"><?php foreach($st->fetchAll() as $p):?><div class="col-lg-6"><div class="service-card p-4"><h5><?=e($p['name'])?></h5><p class="text-secondary"><?=e($p['experience'])?> · PKR <?=number_format($p['charges'],2)?></p><p>Status: <?=badge($p['verification_status'])?></p><a href="provider-details.php?id=<?=$p['id']?>" class="btn btn-outline-secondary btn-sm">View</a><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button name="action" value="approve" class="btn btn-success btn-sm">Approve</button><button name="action" value="reject" class="btn btn-outline-danger btn-sm">Reject</button></form></div></div><?php endforeach;?></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>